//
// ORB pipeline (PocketGS Appendix A.b): FAST → steered BRIEF → brute-force Hamming match + Lowe
// ratio + mutual cross-check, done in GPU kernels. Steered BRIEF is implemented from
// Rublee et al. 2011 §3.2-4.1. Single scale (no pyramid).

import Foundation
import MLX
import MLXFast

public enum ORBPipeline {

    /// Sampling pattern of 256 pairs × (xa, ya, xb, yb). Each coordinate ∈ [-15, 15] (patch 31).
    /// Generated by xorshift64 with a fixed seed.
    public static let pattern256: [Int32] = {
        var rng: UInt64 = 0xACE1_DEAD_BEEF
        func next() -> Int32 {
            rng ^= rng &<< 13
            rng ^= rng &>> 7
            rng ^= rng &<< 17
            return Int32(rng % 31) - 15
        }
        var p = [Int32]()
        p.reserveCapacity(256 * 4)
        for _ in 0..<(256 * 4) { p.append(next()) }
        return p
    }()

    private static let descriptorKernel = SlangCompiledKernel.required("brief_descriptor")

    private static let matchKernel = SlangCompiledKernel.required("brief_match")

    public struct FrameFeatures {
        public let coords: [(x: Int, y: Int)]    // [N] pixel
        public let descriptors: MLXArray         // [N, 8] int32 (256 bit / kp)
        public init(coords: [(x: Int, y: Int)], descriptors: MLXArray) {
            self.coords = coords
            self.descriptors = descriptors
        }
    }

    public struct Match: Sendable, Equatable {
        public let queryIdx: Int     // index into a.coords
        public let trainIdx: Int     // index into b.coords
        public let distance: Int     // Hamming distance 0..256
        public init(queryIdx: Int, trainIdx: Int, distance: Int) {
            self.queryIdx = queryIdx; self.trainIdx = trainIdx; self.distance = distance
        }
    }

    /// Drops train candidates outside the epipolar band (within `bandPx` of `l_b = F · [x_a, y_a,
    /// 1]`) before Hamming. `bandPx` is generous to absorb ARKit pose noise (too narrow also cuts
    /// true matches).
    public struct EpipolarGuide: Sendable {
        public let fundamentalAB: [Float]   // row-major 9
        public let bandPx: Float
        public init(fundamentalAB: [Float], bandPx: Float) {
            self.fundamentalAB = fundamentalAB
            self.bandPx = bandPx
        }
    }

    /// Extracts FAST keypoints + BRIEF descriptors from `[H, W]` float32 luma.
    public static func extract(
        luma: MLXArray, fastThreshold: Float = 0.05, maxKeypoints: Int = 1500
    ) -> FrameFeatures {
        let scoreMap = FASTCorner.score(luma: luma, threshold: fastThreshold)
        let (rawCoords, _) = FASTCorner.extractKeypoints(scoreMap: scoreMap, maxKeypoints: maxKeypoints)
        // The kernel returns a zero descriptor for keypoints whose patch (radius 15) sticks out, so
        // drop them first.
        let h = luma.shape[0]
        let w = luma.shape[1]
        let coords = rawCoords.filter { $0.x >= 15 && $0.x < w - 15 && $0.y >= 15 && $0.y < h - 15 }
        if coords.isEmpty {
            return FrameFeatures(coords: [], descriptors: MLXArray.zeros([0, 8], dtype: .int32))
        }
        var kpFlat = [Int32](repeating: 0, count: coords.count * 2)
        for (i, c) in coords.enumerated() {
            kpFlat[i * 2 + 0] = Int32(c.x)
            kpFlat[i * 2 + 1] = Int32(c.y)
        }
        let kpArr = MLXArray(kpFlat, [coords.count * 2])
        let patternArr = MLXArray(pattern256, [256 * 4])
        let dimsArr = MLXArray([Int32(w), Int32(h), Int32(coords.count)], [3])
        let lumaFlat = luma.reshaped([h * w])
        let outputs = descriptorKernel(
            [lumaFlat, kpArr, patternArr, dimsArr],
            grid: (((coords.count + 63) / 64) * 64, 1, 1),
            threadGroup: (64, 1, 1),
            outputShapes: [[coords.count * 8]],
            outputDTypes: [.int32]
        )
        let desc = outputs[0].reshaped([coords.count, 8])
        eval(desc)
        return FrameFeatures(coords: coords, descriptors: desc)
    }

    /// Brute-force Hamming matching + Lowe ratio + mutual cross-check. Returned in a's keypoint
    /// order.
    public static func match(
        a: FrameFeatures, b: FrameFeatures, loweRatio: Float = 0.8,
        epipolar: EpipolarGuide? = nil
    ) -> [Match] {
        matchBatch([(a: a, b: b, epipolar: epipolar)], loweRatio: loweRatio)[0]
    }

    /// Runs `match` on several pairs together. Waiting for the GPU after each pair makes the round
    /// trips of small kernels (one thread per keypoint) the bottleneck (about 1000 pairs and 2000
    /// waits for a 300-frame capture), so `pairsPerEval` pairs of kernels are enqueued before
    /// waiting once. Results are in pair order, each the same as `match`.
    public static func matchBatch(
        _ pairs: [(a: FrameFeatures, b: FrameFeatures, epipolar: EpipolarGuide?)],
        loweRatio: Float = 0.8, pairsPerEval: Int = 128
    ) -> [[Match]] {
        precondition(pairsPerEval >= 1)
        var results: [[Match]] = []
        results.reserveCapacity(pairs.count)
        for start in stride(from: 0, to: pairs.count, by: pairsPerEval) {
            let pending = pairs[start..<min(pairs.count, start + pairsPerEval)].map {
                enqueueMatch(a: $0.a, b: $0.b, loweRatio: loweRatio, epipolar: $0.epipolar)
            }
            eval(pending.flatMap { p in p.map { [$0.idxAB, $0.distAB, $0.idxBA] } ?? [] })
            for p in pending {
                guard let p else { results.append([]); continue }
                let idxAB = p.idxAB.asArray(Int32.self)
                let distAB = p.distAB.asArray(Int32.self)
                let idxBA = p.idxBA.asArray(Int32.self)
                // Accept only when a → b gives best=k and b → a gives best=i
                var matches: [Match] = []
                matches.reserveCapacity(min(idxAB.count, idxBA.count))
                for i in 0..<idxAB.count {
                    let k = Int(idxAB[i])
                    if k < 0 { continue }
                    if Int(idxBA[k]) != i { continue }
                    matches.append(Match(queryIdx: i, trainIdx: k, distance: Int(distAB[i])))
                }
                results.append(matches)
            }
        }
        return results
    }

    /// Enqueues the a → b / b → a kernels for one pair (no evaluation). nil if there are no
    /// keypoints.
    private static func enqueueMatch(
        a: FrameFeatures, b: FrameFeatures, loweRatio: Float, epipolar: EpipolarGuide?
    ) -> (idxAB: MLXArray, distAB: MLXArray, idxBA: MLXArray)? {
        let Na = a.coords.count
        let Nb = b.coords.count
        if Na == 0 || Nb == 0 { return nil }
        let ratioQ8 = Int32((loweRatio * 256.0).rounded())
        // bandPx <= 0 disables the kernel-side epipolar band filter.
        let bandQ = Int32(max(0, (epipolar?.bandPx ?? 0).rounded()))

        let aFlat = a.descriptors.reshaped([Na * 8])
        let bFlat = b.descriptors.reshaped([Nb * 8])
        let aXY = MLXArray(xyFloats(a.coords), [Na * 2])
        let bXY = MLXArray(xyFloats(b.coords), [Nb * 2])

        // a → b: the line for query a uses F_ab.
        let aLines = MLXArray(epipolarLines(epipolar?.fundamentalAB, a.coords), [Na * 3])
        let dimsAB = MLXArray([Int32(Na), Int32(Nb), ratioQ8, bandQ], [4])
        let outAB = matchKernel(
            [aFlat, bFlat, bXY, aLines, dimsAB],
            grid: (((Na + 63) / 64) * 64, 1, 1),
            threadGroup: (64, 1, 1),
            outputShapes: [[Na], [Na]],
            outputDTypes: [.int32, .int32]
        )

        // b → a (for cross-check): the line for query b uses F_ba = F_abᵀ.
        let bLines = MLXArray(
            epipolarLines(epipolar.map { transpose3($0.fundamentalAB) }, b.coords), [Nb * 3]
        )
        let dimsBA = MLXArray([Int32(Nb), Int32(Na), ratioQ8, bandQ], [4])
        let outBA = matchKernel(
            [bFlat, aFlat, aXY, bLines, dimsBA],
            grid: (((Nb + 63) / 64) * 64, 1, 1),
            threadGroup: (64, 1, 1),
            outputShapes: [[Nb], [Nb]],
            outputDTypes: [.int32, .int32]
        )
        return (outAB[0], outAB[1], outBA[0])
    }

    // MARK: - Epipolar band guide helpers

    /// Converts keypoints to `[N*2]` float at pixel centers (+0.5).
    private static func xyFloats(_ coords: [(x: Int, y: Int)]) -> [Float] {
        var out = [Float](repeating: 0, count: coords.count * 2)
        for (i, c) in coords.enumerated() {
            out[i * 2 + 0] = Float(c.x) + 0.5
            out[i * 2 + 1] = Float(c.y) + 0.5
        }
        return out
    }

    /// Returns epipolar lines `l = F · [x, y, 1]` as `[N*3]`, normalized so `sqrt(l0²+l1²)=1`,
    /// making the kernel's `|l·[xb,yb,1]|` a px distance. 0 if `F == nil` (not read by the kernel).
    private static func epipolarLines(_ F: [Float]?, _ coords: [(x: Int, y: Int)]) -> [Float] {
        var out = [Float](repeating: 0, count: coords.count * 3)
        guard let F, F.count == 9 else { return out }
        for (i, c) in coords.enumerated() {
            let x = Float(c.x) + 0.5
            let y = Float(c.y) + 0.5
            var l0 = F[0] * x + F[1] * y + F[2]
            var l1 = F[3] * x + F[4] * y + F[5]
            var l2 = F[6] * x + F[7] * y + F[8]
            let nrm = (l0 * l0 + l1 * l1).squareRoot()
            if nrm > 1e-12 { l0 /= nrm; l1 /= nrm; l2 /= nrm }
            out[i * 3 + 0] = l0
            out[i * 3 + 1] = l1
            out[i * 3 + 2] = l2
        }
        return out
    }

    private static func transpose3(_ F: [Float]) -> [Float] {
        [F[0], F[3], F[6], F[1], F[4], F[7], F[2], F[5], F[8]]
    }
}
